from math import factorial


def c(n, k):
    if k < 0 or k > n:
        return 0
    else:
        return factorial(n) / factorial(k) / factorial(n - k)


def main():
    n, _, h = list(map(int, input().split()))
    s = list(map(int, input().split()))

    if sum(s) < n:
        print(-1)
    elif s[h - 1] == 1:
        print(0)
    else:
        print(c(sum(s) - s[h - 1], n - 1) / c(sum(s) - 1, n - 1))

