def f(lst):
    n = len(lst)
    d = {-2:0,0:0,1:1}
    for i in range(2,n+1):
        a = lst[-i]
        for j in range(n-i+1,n):
            if lst[j] == a:
                break
        else:
            j = n+1
        d[i] = min(i+j-n-1+d[n-j-1], 1 + d[i-1])
    return d[n]

