def prefix(s):
    i = 0
    c = os.path.commonprefix([s, s[i+1:]])
    while c == "":
        c = os.path.commonprefix([s, s[i+1:]])
        i += 1
        if i == len(s):
            return s
    return prefix(s[len(c):])


