def compute(H, mid):
	if mid <= H:
		return (mid+1)*mid//2
	else:
		remain = mid - H + 1
		ret = (H-1)*H/2 + H * remain
		t = (mid - H) // 2
		if remain % 2:
			ret += t*t
		else
			ret += (t+1)*t
		return ret

