    else:
        if abs(t - h) <= abs(t - (h*2 + c)/3):
            return 1
        i = 2
        while abs(t - (h*(i-1) + c*(i-2))/((i-1)*2-1)) => abs(t - (h*i + c*(i-1))/(i*2-1)) > abs(t - (h*(i+1) + c*(i))/((i+1)*2-1)):
            i += 1
        return int(i*2) - 1


