def solve():
	n, s = [int(x) for x in input().split(' ')]
	if sum([int(x) for x in str(n)]) <= s: return 0
	t, c = str(n), 0
	lt = len(t)
	for k, v in enumerate(t):
		c += int(v)
		if c >= s: 
			if (k == lt - 1 or int(t[k + 1:]) == 0) and c == s:
				return 0
			else:
				return int('1'+'0'*(lt - k)) - int('t[k:])
	return 0


