import math


def solve():
    seals = int(input())
    energies = list(map(int, input().split(" ")))

    res = [0 for i in range(seals)]

    for i in range(0, seals, 2):
        a, b = 2 * energies[i], 2 * energies[i + 1]

        gcd = math.gcd(a, b)

        res[i], res[i + 1] = b//gcd, -1 * (a //gcd)



    return " ".join(map(str, res))


