def bjuti(a,n):
	d={}
	if len(a) <= n:
		return n
	maks=-1
	for c in a:
		if c in d:
			d[c]+=1
		else:
			d[c]=1
		maks = max(maks,d[c])
	if n==1 and len(a)==maks:
        return len(a)-1
	return min(maks+n,len(a))
