using namespace std;
long simpl(long n,long m)
{
	long k=m,t=m*10,r=0;
	while(k<=n && k<t)
	{
		r+=(k%10);
		k+=m;
	}
	if(t<n)
		return r*(n/t)+simpl(n%t,m);
	return r;
}
